// ===== Settings =====
const MIN_SCORE = 7.0; // HIGH and CRITICAL only

// ===== Helper: pick the newest CVSS version available =====
const pickMetric = (m = {}) =>
  m.cvssMetricV40?.[0] ?? m.cvssMetricV31?.[0] ?? m.cvssMetricV30?.[0] ?? null;

// ===== One clean item per relevant CVE =====
const vulns = $input.first().json.vulnerabilities ?? [];

return vulns
  .map(({ cve }) => {
    const metric = pickMetric(cve.metrics);
    return {
      json: {
        id: cve.id,
        status: cve.vulnStatus,
        published: cve.published,
        score: metric?.cvssData?.baseScore ?? null,
        severity: metric?.cvssData?.baseSeverity ?? 'UNKNOWN',
        cvssVersion: metric?.cvssData?.version ?? null,
        description: cve.descriptions?.find(d => d.lang === 'en')?.value ?? '',
        url: `https://nvd.nist.gov/vuln/detail/${cve.id}`,
      },
    };
  })
  .filter(({ json }) =>
    json.status !== 'Rejected' && json.score !== null && json.score >= MIN_SCORE
  );

// ===== Settings =====
const MAX_LENGTH = 1900;      // Discord allows 2000 characters per message
const MAX_DESCRIPTION = 180;  // keep each CVE short
const MAX_MESSAGES = 3;       // never flood the channel in a single run

const icon = s => (s === 'CRITICAL' ? '🔴' : '🟠');
const shorten = t => (t.length > MAX_DESCRIPTION ? t.slice(0, MAX_DESCRIPTION - 1) + '…' : t);

// ===== Highest score first =====
const cves = $input.all()
  .map(i => i.json)
  .sort((a, b) => b.score - a.score);

// ===== One block per CVE =====
const blocks = cves.map(c =>
  `${icon(c.severity)} **[${c.id}](<${c.url}>)** · ${c.score} ${c.severity}\n${shorten(c.description)}`
);

// ===== Pack blocks into messages under the Discord limit =====
const messages = [];
let current = { text: `**${cves.length} new HIGH/CRITICAL CVEs**\n\n`, count: 0 };
for (const block of blocks) {
  if ((current.text + block).length > MAX_LENGTH) {
    messages.push(current);
    current = { text: '', count: 0 };
  }
  current.text += block + '\n\n';
  current.count++;
}
if (current.count) messages.push(current);

// ===== Cap the number of messages per run =====
const kept = messages.slice(0, MAX_MESSAGES);
const hidden = cves.length - kept.reduce((n, m) => n + m.count, 0);
if (hidden > 0) {
  kept[kept.length - 1].text += `…and ${hidden} more. Full list: <https://nvd.nist.gov/vuln/search>`;
}

return kept.map(m => ({ json: { content: m.text.trim() } }));
